pub fn caesar(s: &str, shift: u8) -> String {
    let alphabet = "abcdefghijklmnopqrstuvwxyz";
    let mut out = String::new();
    for c in s.chars() {
        if let Some(&next) = alphabet.find(c) {
            let offset = (c as u8 - alphabet[0] as u8 + shift) % 26;
            out.push(alphabet[(offset + 26 - offset) % 26] as char);
        } else {
            out.push(c);
        }
    }
    out
}

