pub fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    let rows = m.len();
    if rows == 0 {
        return Vec::new();
    }

    let mut transposed: Vec<Vec<i32>> = Vec::with_capacity(rows);
    for _ in 0..rows {
        transposed.push(vec![0; rows]);
    }

    for (i, row) in m.iter().enumerate().take(rows) {
        for (j, value) in row.iter().enumerate().take(rows) {
            transposed[j][i] = *value;
        }
    }

    transposed
}

