pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 7 || s.chars().next().unwrap() != '#' {
        return None;
    }

    let (r, g, b) = s
        .chars()
        .skip(1)
        .map(|c| c.to_digit(16).unwrap())
        .collect::<Vec<u8>>();

    if r > 255 || g > 255 || b > 255 {
        return None;
    }

    Some((r, g, b))
}

